def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # The replacement color is indicated by a long straight run.
    runs = Counter()
    for r in range(h):
        c = 0
        while c < w:
            color, start = grid[r][c], c
            while c < w and grid[r][c] == color:
                c += 1
            if color != bg and c - start >= 5:
                runs[color] += c - start
    for c in range(w):
        r = 0
        while r < h:
            color, start = grid[r][c], r
            while r < h and grid[r][c] == color:
                r += 1
            if color != bg and r - start >= 5:
                runs[color] += r - start

    if not runs:
        return [row[:] for row in grid]
    replacement = runs.most_common(1)[0][0]

    # Find same-color connected components; recolor the largest component
    # whose color is not the line-marker color.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            comps.append((color, cells))

    candidates = [obj for obj in comps if obj[0] != replacement]
    if not candidates:
        return [row[:] for row in grid]
    color, cells = max(candidates, key=lambda obj: len(obj[1]))
    out = [row[:] for row in grid]
    for r, c in cells:
        out[r][c] = replacement
    return out
